body {
  margin: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: #f9fafb;
  color: #111827;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

#app {
  text-align: center;
  padding: 2rem;
  background: white;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
  width: 100%;
  max-width: 1200px;
}

import { renderSummaryCards } from './components/SummaryCards.js';
import { renderTransactionList } from './components/TransactionList.js';
import { openTransactionModal } from './components/TransactionForm.js';
import { renderFinanceChart } from './components/FinanceChart.js';

let transactions = JSON.parse(localStorage.getItem('transactions')) || [];

const saveState = () => {
    localStorage.setItem('transactions', JSON.stringify(transactions));
};

const updateUI = () => {
    const summaryContainer = document.getElementById('summarycards-container');
    const listContainer = document.getElementById('transactionlist-container');
    const chartContainer = document.getElementById('financechart-container');

    if (summaryContainer) renderSummaryCards(transactions, summaryContainer);
    if (listContainer) renderTransactionList(transactions, listContainer);
    if (chartContainer) renderFinanceChart(transactions, chartContainer);
};

window.addEventListener('add-transaction', (e) => {
    const newTransaction = {
        ...e.detail,
        id: Date.now()
    };
    transactions.push(newTransaction);
    saveState();
    updateUI();
});

window.addEventListener('delete-transaction', (e) => {
    const id = parseInt(e.detail.id);
    transactions = transactions.filter(t => t.id !== id);
    saveState();
    updateUI();
});

document.addEventListener('DOMContentLoaded', () => {
    const addBtn = document.getElementById('add-transaction-btn');
    if (addBtn) {
        addBtn.addEventListener('click', () => {
            openTransactionModal();
        });
    }

    updateUI();
});

export { transactions };

export function renderSummaryCards(transactions) {
  const container = document.getElementById('summarycards-container');
  if (!container) return;

  const income = transactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  const expense = transactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  const balance = income - expense;

  const formatCurrency = (val) => new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD'
  }).format(val);

  container.innerHTML = `
    <div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
      <div class="bg-white p-6 rounded-lg shadow border-l-4 border-green-500">
        <h3 class="text-sm font-semibold text-gray-500 uppercase">Balance</h3>
        <p class="text-2xl font-bold text-gray-800">${formatCurrency(balance)}</p>
      </div>
      <div class="bg-white p-6 rounded-lg shadow border-l-4 border-blue-500">
        <h3 class="text-sm font-semibold text-gray-500 uppercase">Income</h3>
        <p class="text-2xl font-bold text-green-600">${formatCurrency(income)}</p>
      </div>
      <div class="bg-white p-6 rounded-lg shadow border-l-4 border-red-500">
        <h3 class="text-sm font-semibold text-gray-500 uppercase">Expenses</h3>
        <p class="text-2xl font-bold text-red-600">${formatCurrency(expense)}</p>
      </div>
    </div>
  `;
}

import { Chart, registerables } from 'chart.js';

Chart.register(...registerables);

let chartInstance = null;

export function renderFinanceChart(transactions) {
  const container = document.getElementById('financechart-container');
  if (!container) return;

  container.innerHTML = '<canvas id="finance-canvas" class="w-full h-64"></canvas>';
  const canvas = document.getElementById('finance-canvas');

  const income = transactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  const expense = transactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  if (chartInstance) {
    chartInstance.destroy();
  }

  chartInstance = new Chart(canvas, {
    type: 'doughnut',
    data: {
      labels: ['Income', 'Expenses'],
      datasets: [{
        data: [income, expense],
        backgroundColor: ['#10B981', '#EF4444'],
        borderWidth: 0
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: 'bottom'
        }
      }
    }
  });
}

export function openTransactionModal() {
  const overlay = document.createElement('div');
  overlay.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50';

  const modal = document.createElement('div');
  modal.className = 'bg-white rounded-lg p-6 w-full max-w-md shadow-xl';
  modal.innerHTML = `
    <h2 class="text-xl font-bold mb-4">Add Transaction</h2>
    <form id="transaction-form" class="space-y-4">
      <div>
        <label class="block text-sm font-medium text-gray-700">Description</label>
        <input type="text" id="desc" required class="w-full border rounded p-2 mt-1">
      </div>
      <div>
        <label class="block text-sm font-medium text-gray-700">Amount</label>
        <input type="number" id="amount" required step="0.01" class="w-full border rounded p-2 mt-1">
      </div>
      <div>
        <label class="block text-sm font-medium text-gray-700">Type</label>
        <select id="type" class="w-full border rounded p-2 mt-1">
          <option value="income">Income</option>
          <option value="expense">Expense</option>
        </select>
      </div>
      <div class="flex justify-end gap-2 mt-6">
        <button type="button" id="cancel-btn" class="px-4 py-2 text-gray-600">Cancel</button>
        <button type="submit" class="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">Save</button>
      </div>
    </form>
  `;

  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  const closeModal = () => overlay.remove();

  overlay.querySelector('#cancel-btn').addEventListener('click', closeModal);

  modal.querySelector('#transaction-form').addEventListener('submit', (e) => {
    e.preventDefault();

    const transaction = {
      id: Date.now(),
      description: document.getElementById('desc').value,
      amount: parseFloat(document.getElementById('amount').value),
      type: document.getElementById('type').value,
      date: new Date().toISOString()
    };

    window.dispatchEvent(new CustomEvent('add-transaction', { detail: transaction }));
    closeModal();
  });

  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closeModal();
  });
}

export function renderTransactionList(transactions = [], filterQuery = '', filterCategory = 'All') {
  const container = document.getElementById('transactionlist-container');
  if (!container) return;

  const filtered = transactions.filter(t => {
    const matchesQuery = t.description.toLowerCase().includes(filterQuery.toLowerCase());
    const matchesCategory = filterCategory === 'All' || t.category === filterCategory;
    return matchesQuery && matchesCategory;
  });

  let html = `
    <div class="bg-white p-6 rounded-lg shadow-md">
      <div class="flex gap-4 mb-4">
        <input type="text" id="search-input" placeholder="Search..." value="${filterQuery}" class="border p-2 rounded w-full">
        <select id="category-filter" class="border p-2 rounded">
          <option value="All">All Categories</option>
          <option value="Income" ${filterCategory === 'Income' ? 'selected' : ''}>Income</option>
          <option value="Expense" ${filterCategory === 'Expense' ? 'selected' : ''}>Expense</option>
        </select>
      </div>
      <table class="w-full text-left border-collapse">
        <thead>
          <tr class="border-b">
            <th class="py-2">Description</th>
            <th class="py-2">Category</th>
            <th class="py-2">Amount</th>
            <th class="py-2">Action</th>
          </tr>
        </thead>
        <tbody>
          ${filtered.map(t => `
            <tr class="border-b">
              <td class="py-2">${t.description}</td>
              <td class="py-2">${t.category}</td>
              <td class="py-2 ${t.category === 'Income' ? 'text-green-600' : 'text-red-600'}">
                ${t.category === 'Income' ? '+' : '-'}$${Math.abs(t.amount).toFixed(2)}
              </td>
              <td class="py-2">
                <button data-id="${t.id}" class="delete-btn text-red-500 hover:text-red-700">Delete</button>
              </td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;

  container.innerHTML = html;

  container.querySelector('#search-input').addEventListener('input', (e) => {
    window.dispatchEvent(new CustomEvent('filter-changed', { 
      detail: { query: e.target.value, category: container.querySelector('#category-filter').value } 
    }));
  });

  container.querySelector('#category-filter').addEventListener('change', (e) => {
    window.dispatchEvent(new CustomEvent('filter-changed', { 
      detail: { query: container.querySelector('#search-input').value, category: e.target.value } 
    }));
  });

  container.querySelectorAll('.delete-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      window.dispatchEvent(new CustomEvent('delete-transaction', { 
        detail: { id: e.target.dataset.id } 
      }));
    });
  });
}
